from PIL import Image, UnidentifiedImageError
import torch

def safe_pil_loader(path):
    try:
        with open(path, 'rb') as f:
            img = Image.open(f)
            img.load()  # Force load to verify it's valid
            return img.convert('RGB')
    except (OSError, UnidentifiedImageError, Exception) as e:
        return None

# Transformations
transformations = transforms.Compose([transforms.Resize((256, 256)), transforms.ToTensor()])

# Create ImageFolder to get samples
base_dataset = ImageFolder(directory_path, transform=None)

# Filter out invalid samples
valid_samples = []
for path, target in base_dataset.samples:
    if safe_pil_loader(path) is not None:
        valid_samples.append((path, target))

print(f"Filtered {len(base_dataset.samples)} down to {len(valid_samples)} valid samples")

# Create a custom dataset class that uses valid samples
class FilteredImageFolder(torch.utils.data.Dataset):
    def __init__(self, samples, transform=None):
        self.samples = samples
        self.transform = transform
        self.classes = base_dataset.classes
        self.class_to_idx = base_dataset.class_to_idx

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, index):
        path, target = self.samples[index]
        img = safe_pil_loader(path)
        if img is None:
            # Fallback to first sample if somehow still fails
            img = safe_pil_loader(self.samples[0][0])
            target = self.samples[0][1]
        if self.transform is not None:
            img = self.transform(img)
        return img, target

# Create the filtered dataset
dataset = FilteredImageFolder(valid_samples, transform=transformations)
print(f"Dataset created with {len(dataset)} samples")"}

